// Lee la petición del webhook (GET ?mensaje=...&session_id=...&id=...) y arma el caso con su código único.
const q = $input.first().json.query || {};
const mensaje = String(q.mensaje || '').trim().slice(0, 600);
const session_id = String(q.session_id || 'anonimo').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 40) || 'anonimo';
const idCliente = String(q.id || '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 60);
// Clave de idempotencia: el id que manda el cliente; si no manda, sesión + mensaje + ventana de 5 minutos.
let clave;
if (idCliente) clave = 'id-' + idCliente;
else {
  let h = 5381; const s = (session_id + '|' + mensaje.toLowerCase());
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  clave = 'h-' + h.toString(36) + '-' + Math.floor(Date.now() / 300000);
}
return [{ json: {
  traceId: 'F-' + Date.now(),
  clave_idempotencia: clave,
  session_id, mensaje,
  valido: mensaje.length > 0,
  fecha_recepcion: new Date().toISOString(),
  intentos: 0, critica_previa: '', respuesta_previa: '', resumen_previo: '', costo_acumulado: 0
} }];

// Si la misma petición ya se completó (o sigue en proceso hace menos de 15 minutos) no se vuelve a procesar.
// Una petición con estado 'error' sí se puede reintentar.
const base = $('Preparar_Solicitud').first().json;
const filas = $input.all().map(i => (i.json.fields || i.json));
const ahora = Date.now();
const dup = filas.some(f => {
  if (!f || !f.estado) return false;
  if (f.estado === 'completado') return true;
  if (f.estado === 'en_proceso') {
    const t = Date.parse(f.fecha_recepcion || '');
    return isNaN(t) ? true : (ahora - t) < 15 * 60 * 1000;
  }
  return false;
});
return [{ json: { ...base, es_duplicado: dup } }];

// Suma la memoria de la sesión al caso. Si la memoria falló, sigue sin historial.
const base = $('Restaurar_Estado').first().json;
const r = $input.first().json || {};
return [{ json: { ...base, resumen_previo: r.resumen_previo || '', cantidad_mensajes_previa: r.cantidad_mensajes || 0 } }];

const base = $('Preparar_Entrada_Agente').first().json;
const r = $input.first().json;
return [{ json: { ...base,
  respuesta_agente: r.respuesta_agente, contexto_recuperado: r.contexto_recuperado, fuentes_citadas: r.fuentes_citadas || [],
  paginas_recuperadas: r.paginas_recuperadas || [], cita_valida: r.cita_valida, respondio_no_se: r.respondio_no_se, uso_rag: r.uso_rag } }];

const base = $('Fusionar_Agente').first().json;
const r = $input.first().json;
return [{ json: { ...base,
  exactitud_factual: r.exactitud_factual, estado_veredicto: r.estado_veredicto, cita_correcta: r.cita_correcta,
  critica: r.critica, ruta_final: r.ruta_final, tokens_entrada: r.tokens_entrada, tokens_salida: r.tokens_salida,
  costo_usd: r.costo_usd, costo_acumulado: Number(((base.costo_acumulado || 0) + r.costo_usd).toFixed(6)),
  veredicto_json: r.veredicto_json } }];

// Marca el modo de despacho: aceptada
const d = $input.first().json;
return [{ json: { ...d, modo: 'aceptada', aprobado_por: 'Controlador IA (nota ' + d.exactitud_factual + '/5)' } }];

// Ruta Corregir: vuelve al asistente con la crítica del controlador. intentos sube de a 1 (máximo 2).
const d = $input.first().json;
return [{ json: { ...d, intentos: d.intentos + 1, critica_previa: d.critica, respuesta_previa: d.respuesta_agente } }];

