// Marca el modo de despacho: aprobada_humano
const d = $('Fusionar_Juez').first().json;
return [{ json: { ...d, modo: 'aprobada_humano', aprobado_por: 'Persona (botón Aprobar)' } }];

// Marca el modo de despacho: edicion_manual
const d = $('Fusionar_Juez').first().json;
return [{ json: { ...d, modo: 'edicion_manual', aprobado_por: 'Persona (botón Editar)' } }];

const base = $('Fusionar_Juez').first().json;
const r = $input.first().json;
return [{ json: { ...base, modo: r.modo, aprobado_por: r.aprobado_por, ruta_final_registrada: r.ruta_final_registrada,
  estado_despacho: r.estado_despacho, canal: r.canal } }];

const d = $('Fusionar_Despacho').first().json;
const resumen = JSON.stringify({ exactitud_factual: d.exactitud_factual, aprobado_por: d.aprobado_por, ruta: d.ruta_final_registrada,
  fuentes: (d.fuentes_citadas || []).join(' | '), costo_usd: d.costo_acumulado, respuesta: String(d.respuesta_agente || '').slice(0, 300) });
return [{ json: { clave_idempotencia: d.clave_idempotencia, traceId: d.traceId, estado: 'completado',
  ruta_final: d.ruta_final_registrada, resultado: resumen } }];

// Rama de error: arma el aviso para el equipo humano con el paso que falló y el código del caso.
const pasos = [
  ['Airtable_Buscar_Duplicado', 'el libro de recepción (Airtable)'],
  ['Airtable_Registrar_Recepcion', 'el libro de recepción (Airtable)'],
  ['Execute_Worker_Memoria', 'la memoria de la conversación'],
  ['Execute_Worker_Agente_RAG', 'el asistente que consulta el manual'],
  ['Execute_Worker_Juez', 'el controlador de calidad'],
  ['Execute_Worker_Despacho', 'el despacho (borrador de Gmail y registro en el CRM)']
];
let falla = 'un paso del sistema';
for (const [n, d] of pasos) { try { if ($(n).isExecuted) falla = d; } catch (e) {} }
const e = $input.first().json || {};
const motivo = String((e.error && (e.error.message || e.error)) || e.message || 'sin detalle').slice(0, 300);
const base = $('Preparar_Solicitud').first().json;
const asunto = 'ALERTA - consulta sin responder (caso ' + base.traceId + ')';
const cuerpo = [
  'Una consulta de un paciente no pudo completarse porque falló ' + falla + '.',
  '',
  'Código de caso: ' + base.traceId,
  'Qué pasó: ' + motivo,
  'Estado: la consulta quedó registrada como error y el paciente todavía no recibió respuesta.',
  '',
  'Qué hacer: una persona debe responder esta consulta a mano, o volver a enviarla cuando el servicio se recupere. '
  + 'El sistema no duplica registros ni envíos, así que reenviar es seguro.'
].join('\n');
return [{ json: { ...base, estado: 'error', ruta_final: 'ERROR', resultado: 'Falla en ' + falla + ': ' + motivo, asunto, cuerpo } }];
